"""Module 3 \u2014 context bundler.

Takes a :class:`Candidate` and a graph, walks the local neighborhood up
to the configured hop budget, pulls code snippets, and packs everything
into a :class:`ContextBundle` with a deterministic :class:`PackManifest`.

Truncation order is explicit (documented on the manifest):
1. least-central call_chain nodes (furthest hop first)
2. duplicate-looking code snippets (same file, same function)
3. largest snippets trimmed to their first/last 20 lines

Token estimator defaults to ``chars4`` (``len(text) // 4``). If
``config.bundles.allow_tiktoken`` and tiktoken is available, the
estimator switches to ``tiktoken-cl100k``. The chosen estimator name is
always written into the manifest so downstream consumers can reproduce
the budget calculation.
"""
from __future__ import annotations

import hashlib
import re
from pathlib import Path
from typing import TYPE_CHECKING, Optional

import networkx as nx

if TYPE_CHECKING:
    from depos.analysis.run_context import RunContext

from depos.analysis.config import IntelligenceConfig
from depos.analysis.schemas import (
    BundleEdgeFact,
    BundleEvidence,
    BundleNodeFact,
    Candidate,
    CodeSnippet,
    ContextBundle,
    MigrationState,
    PackManifest,
    RLSCoverage,
    SeamEdge,
    SemanticEdgeMetadata,
    TaintEdge,
)


_QUALITY_RANK = {"missing": 0, "label_only": 1, "embedded": 2, "full": 3}
_RE_TS_NON_NULL = re.compile(r"\b\w+!\s*\.\s*\w+")
_RE_PY_OPTIONAL_DEREF = re.compile(r"\b\w+\s*\.\s*\w+")


# ---------------------------------------------------------------------------
# Token estimators
# ---------------------------------------------------------------------------


def _chars4(text: str) -> int:
    return max(1, len(text) // 4)


def _get_estimator(config: IntelligenceConfig):
    name = config.bundles.token_estimator
    if name == "tiktoken-cl100k" and config.bundles.allow_tiktoken:
        try:
            import tiktoken  # type: ignore

            enc = tiktoken.get_encoding("cl100k_base")

            def _tt(text: str) -> int:
                return len(enc.encode(text))

            return _tt, "tiktoken-cl100k"
        except Exception:  # noqa: BLE001
            return _chars4, "chars4"
    return _chars4, "chars4"


# ---------------------------------------------------------------------------
# Graph walks
# ---------------------------------------------------------------------------


def _walk_callers(graph: nx.DiGraph, start: str, hops: int) -> list[dict]:
    out: list[dict] = []
    frontier = {start}
    for depth in range(1, hops + 1):
        next_frontier: set[str] = set()
        for n in frontier:
            for u, _ in graph.in_edges(n):
                out.append({"node_id": u, "depth": depth})
                next_frontier.add(u)
        frontier = next_frontier
        if not frontier:
            break
    return out


def _walk_callees(graph: nx.DiGraph, start: str, hops: int) -> list[dict]:
    out: list[dict] = []
    frontier = {start}
    for depth in range(1, hops + 1):
        next_frontier: set[str] = set()
        for n in frontier:
            for _, v in graph.out_edges(n):
                out.append({"node_id": v, "depth": depth})
                next_frontier.add(v)
        frontier = next_frontier
        if not frontier:
            break
    return out


def _collect_seams(graph: nx.DiGraph, nodes: set[str]) -> list[SeamEdge]:
    out: list[SeamEdge] = []
    for u, v, data in graph.edges(data=True):
        if u not in nodes and v not in nodes:
            continue
        if not (data.get("source_system") and data.get("target_system")):
            continue
        metadata = SemanticEdgeMetadata.model_validate({k2: v2 for k2, v2 in data.items() if k2 != "relation"})
        eid = str(data.get("edge_id") or f"{u}->{v}")
        seam_info = dict(data.get("seam") or {})
        source_attrs = graph.nodes[u] if graph.has_node(u) else {}
        target_attrs = graph.nodes[v] if graph.has_node(v) else {}
        out.append(
            SeamEdge(
                edge_id=eid,
                source=u,
                target=v,
                relation=data.get("relation", ""),
                source_language=str(
                    seam_info.get("source_language")
                    or source_attrs.get("language")
                    or source_attrs.get("lang")
                    or ""
                ),
                target_language=str(
                    seam_info.get("target_language")
                    or target_attrs.get("language")
                    or target_attrs.get("lang")
                    or ""
                ),
                pattern=str(seam_info.get("pattern") or "unknown"),
                contract_defined=bool(seam_info.get("contract_defined", False)),
                contract_verified=bool(seam_info.get("contract_verified", False)),
                metadata=metadata,
            )
        )
    return out


def _collect_taint_edges(graph: nx.DiGraph, nodes: set[str]) -> list[TaintEdge]:
    """Include pre-computed :class:`TaintEdge` rows that touch the bundle neighborhood."""
    out: list[TaintEdge] = []
    for item in list(graph.graph.get("taint_edges", []) or []):
        te = item if isinstance(item, TaintEdge) else TaintEdge.model_validate(item)
        if te.scope in nodes:
            out.append(te)
            continue
        if te.source_node in nodes or te.sink_node in nodes:
            out.append(te)
            continue
        if any(n in nodes for n in te.intermediate_path):
            out.append(te)
    return out


def _endpoints_from_canonical_edge_id(edge_id: str) -> tuple[str, str] | None:
    """Parse ``u->v`` from graph ``edge_id`` (``build_seam_edge_index``)."""
    s = str(edge_id)
    if "->" not in s:
        return None
    u, v = s.split("->", 1)
    if u and v:
        return u, v
    return None


def _collect_data_reads_writes(graph: nx.DiGraph, nodes: set[str]) -> tuple[list[str], list[str]]:
    reads: list[str] = []
    writes: list[str] = []
    for n in nodes:
        if not graph.has_node(n):
            continue
        for _, v, data in graph.out_edges(n, data=True):
            rel = data.get("relation")
            tbl = data.get("table_name") or data.get("rpc_name") or v
            if rel == "ROUTE_READS_TABLE":
                reads.append(tbl)
            elif rel == "ROUTE_WRITES_TABLE":
                writes.append(tbl)
    return sorted(set(reads)), sorted(set(writes))


def _collect_rls(graph: nx.DiGraph, nodes: set[str]) -> dict[str, RLSCoverage]:
    out: dict[str, RLSCoverage] = {}
    for n in nodes:
        if not graph.has_node(n):
            continue
        per_table = graph.nodes[n].get("rls_coverage_per_table", {})
        for tbl, cov_val in per_table.items():
            try:
                out[tbl] = RLSCoverage(cov_val)
            except ValueError:
                continue
    return out


def _collect_migration_state(graph: nx.DiGraph) -> dict[str, MigrationState]:
    out: dict[str, MigrationState] = {}
    for _, attrs in graph.nodes(data=True):
        if attrs.get("file_type") != "sql_table":
            continue
        label = attrs.get("label", "")
        if not label:
            continue
        # Simplified: if the table has at least one SCHEMA_DEFINED_BY_MIGRATION
        # outgoing edge, mark exists_in_branch. Module 1 already enforces
        # lexical ordering; the verifier refines this per-candidate.
        out[label] = MigrationState.exists_in_branch
    return out


# ---------------------------------------------------------------------------
# Code snippet collection
# ---------------------------------------------------------------------------


def _apply_aliases(rel_path: str, aliases: dict[str, str]) -> list[str]:
    """Return the original path plus every aliased rewrite. Order matters."""
    candidates = [rel_path]
    for src, dst in aliases.items():
        if not src:
            continue
        if rel_path.startswith(src):
            candidates.append(dst + rel_path[len(src) :])
    return candidates


def _try_read_source(
    sf: str,
    *,
    source_roots: list[Path],
    path_aliases: dict[str, str],
) -> tuple[str, Optional[str]]:
    """Read file text trying every (root, alias) pair. Returns ``(text, resolved_via)``.

    ``resolved_via`` is a string like ``"<root>::<rel>"`` so we can report
    which root won. Empty when nothing resolved.
    """
    sf_path = Path(sf)
    if sf_path.is_absolute():
        try:
            return sf_path.read_text(encoding="utf-8", errors="replace"), str(sf_path)
        except OSError:
            return "", None

    for root in source_roots:
        for candidate_rel in _apply_aliases(sf, path_aliases):
            target = root / candidate_rel
            try:
                return target.read_text(encoding="utf-8", errors="replace"), f"{root}::{candidate_rel}"
            except OSError:
                continue
    return "", None


def _read_snippet_for(
    node_attrs: dict,
    *,
    source_roots: list[Path],
    path_aliases: dict[str, str],
    min_snippet_chars: int,
) -> Optional[CodeSnippet]:
    sf = node_attrs.get("source_file")
    embedded_text = str(node_attrs.get("embedded_text") or "").strip()
    label = str(node_attrs.get("label") or "").strip()
    if not sf and not embedded_text and not label:
        return None

    start, end = _start_end_lines(node_attrs)

    text = ""
    resolved_via: Optional[str] = None
    if sf:
        text, resolved_via = _try_read_source(
            sf, source_roots=source_roots, path_aliases=path_aliases
        )

    snippet_text = ""
    quality = "missing"
    if text and start > 0 and end >= start:
        lines = text.splitlines()
        snippet_text = "\n".join(lines[max(0, start - 1) : end])
        quality = "full" if snippet_text.strip() else "missing"
    elif text:
        snippet_text = text
        quality = "full" if snippet_text.strip() else "missing"

    if (not snippet_text or len(snippet_text) < min_snippet_chars) and embedded_text:
        # Embedded text is what the dataset normalizer captured at ingest
        # time; treat it as second-best evidence rather than dropping the
        # node entirely.
        if not snippet_text:
            snippet_text = embedded_text
            quality = "embedded"
        elif len(embedded_text) > len(snippet_text):
            snippet_text = embedded_text
            quality = "embedded"

    if not snippet_text and label:
        snippet_text = label
        quality = "label_only"

    if not snippet_text.strip():
        return None

    return CodeSnippet(
        node_id=node_attrs.get("id", ""),
        source_file=sf,
        start_line=start,
        end_line=end,
        text=snippet_text,
        evidence_quality=quality,  # type: ignore[arg-type]
        resolved_via=resolved_via,
    )


def _start_end_lines(node_attrs: dict) -> tuple[int, int]:
    span = node_attrs.get("span") or {}
    start = int(
        node_attrs.get("start_line")
        or (span.get("start") or {}).get("line")
        or node_attrs.get("lineno")
        or 0
    )
    end = int(
        node_attrs.get("end_line")
        or (span.get("end") or {}).get("line")
        or start
        or 0
    )
    return start, end


def _node_language(attrs: dict) -> str:
    for key in ("language", "lang", "source_language"):
        raw = attrs.get(key)
        if raw:
            return str(raw)
    return ""


def _node_universe(attrs: dict) -> str:
    node_kind = str(attrs.get("node_kind") or attrs.get("kind") or "")
    if node_kind in {"package_manifest", "package_dep", "lockfile_resolution"}:
        return "deps"
    if node_kind in {"env_var", "config_key"}:
        return "env"
    if node_kind == "prompt_template":
        return "prompt"
    if node_kind in {"openapi_operation", "openapi_schema"}:
        return "schema"
    if node_kind in {"next_route", "next_middleware"}:
        return "nextjs"
    if node_kind in {"infra_workflow", "infra_service", "dockerfile_stage"}:
        return "infra"
    return str(attrs.get("universe") or attrs.get("source_system") or "code")


def _snippet_for_node(
    graph: nx.DiGraph,
    node_id: str,
    *,
    source_roots: list[Path],
    path_aliases: dict[str, str],
    min_snippet_chars: int,
) -> Optional[CodeSnippet]:
    if not graph.has_node(node_id):
        return None
    return _read_snippet_for(
        {**graph.nodes[node_id], "id": node_id},
        source_roots=source_roots,
        path_aliases=path_aliases,
        min_snippet_chars=min_snippet_chars,
    )


def _fallback_node_text(attrs: dict) -> str:
    for key in ("source", "code", "embedded_text", "label", "name"):
        raw = str(attrs.get(key) or "").strip()
        if raw:
            return raw
    return ""


def _text_for_node(
    graph: nx.DiGraph,
    node_id: str,
    *,
    source_roots: list[Path],
    path_aliases: dict[str, str],
    min_snippet_chars: int,
) -> str:
    snippet = _snippet_for_node(
        graph,
        node_id,
        source_roots=source_roots,
        path_aliases=path_aliases,
        min_snippet_chars=min_snippet_chars,
    )
    if snippet is not None and snippet.text.strip():
        return snippet.text
    if not graph.has_node(node_id):
        return ""
    return _fallback_node_text(graph.nodes[node_id])


def _sort_by_pagerank(node_ids: list[str], pagerank: dict[str, float]) -> list[str]:
    return sorted(
        dict.fromkeys(node_ids),
        key=lambda nid: (-float(pagerank.get(nid, 0.0)), nid),
    )


def _is_call_graph_edge(data: dict) -> bool:
    if data.get("source_system") and data.get("target_system"):
        return False
    relation = str(data.get("relation") or data.get("label") or "").upper()
    return "CALL" in relation or "INVOK" in relation


def _direct_callers(graph: nx.DiGraph, scope_node_id: str, pagerank: dict[str, float]) -> list[str]:
    node_ids = [
        str(u)
        for u, _, data in graph.in_edges(scope_node_id, data=True)
        if _is_call_graph_edge(data)
    ]
    return _sort_by_pagerank(node_ids, pagerank)[:5]


def _direct_callees(graph: nx.DiGraph, scope_node_id: str, pagerank: dict[str, float]) -> list[str]:
    node_ids = [
        str(v)
        for _, v, data in graph.out_edges(scope_node_id, data=True)
        if _is_call_graph_edge(data)
    ]
    return _sort_by_pagerank(node_ids, pagerank)


def _graph_distance_to_diff(
    graph: nx.DiGraph,
    scope_node_id: str,
    diff_anchors: list[str],
) -> int:
    if not scope_node_id or not diff_anchors or not graph.has_node(scope_node_id):
        return -1
    targets = [node_id for node_id in diff_anchors if graph.has_node(node_id)]
    if not targets:
        return -1
    if scope_node_id in targets:
        return 0
    try:
        lengths = nx.single_source_shortest_path_length(graph.to_undirected(as_view=True), scope_node_id)
    except Exception:  # noqa: BLE001
        return -1
    distances = [int(lengths[target]) for target in targets if target in lengths]
    return min(distances) if distances else -1


def _cfg_nodes_for_scope(graph: nx.DiGraph, scope_node_id: str) -> list[str]:
    return [
        str(node_id)
        for node_id, attrs in graph.nodes(data=True)
        if attrs.get("type") == "cfg_block" and attrs.get("parent_scope") == scope_node_id
    ]


def _cfg_summary(graph: nx.DiGraph, scope_node_id: str) -> str:
    cfg_nodes = _cfg_nodes_for_scope(graph, scope_node_id)
    cfg_edges = [
        data
        for u, v, data in graph.edges(data=True)
        if data.get("type") == "cfg" and u in cfg_nodes and v in cfg_nodes
    ]
    branch_edges = sum(1 for data in cfg_edges if data.get("kind") in {"if_true", "if_false", "switch_case"})
    back_edges = sum(1 for data in cfg_edges if data.get("kind") == "back_edge")
    await_edges = sum(1 for data in cfg_edges if data.get("kind") == "await_suspend")
    exit_nodes = sum(1 for node_id in cfg_nodes if str(graph.nodes[node_id].get("label") or "") == "exit")
    if not cfg_nodes:
        return "CFG available for this scope, but no block summary was captured."
    return (
        f"CFG for {scope_node_id}: {len(cfg_nodes)} blocks from entry to {exit_nodes or 1} exit node(s), "
        f"with {branch_edges} branch edge(s), {back_edges} loop back edge(s), and {await_edges} await suspension edge(s)."
    )


def _null_paths_for_scope(
    graph: nx.DiGraph,
    scope_node_id: str,
    *,
    language: str,
    scope_text: str,
) -> list[list[str]]:
    cfg_nodes = _cfg_nodes_for_scope(graph, scope_node_id)
    if not cfg_nodes:
        return []
    ordered_cfg = sorted(cfg_nodes, key=lambda node_id: int(graph.nodes[node_id].get("line") or 0))
    lines = scope_text.splitlines()
    out: list[list[str]] = []

    if language.lower() in {"javascript", "typescript", "js", "ts", "tsx", "jsx"}:
        for node_id in ordered_cfg:
            line_no = int(graph.nodes[node_id].get("line") or 0)
            if line_no <= 0 or line_no > len(lines):
                continue
            if _RE_TS_NON_NULL.search(lines[line_no - 1]):
                out.append([scope_node_id, node_id])
    elif language.lower() in {"python", "py"}:
        prior_none_return = any("return None" in line for line in lines)
        if prior_none_return:
            for node_id in ordered_cfg:
                line_no = int(graph.nodes[node_id].get("line") or 0)
                if line_no <= 0 or line_no > len(lines):
                    continue
                line = lines[line_no - 1]
                if "if " in line and " is None" in line:
                    continue
                if _RE_PY_OPTIONAL_DEREF.search(line) and "None" not in line:
                    out.append([scope_node_id, node_id])
    return out


def _collect_node_facts(graph: nx.DiGraph, nodes: set[str]) -> dict[str, BundleNodeFact]:
    out: dict[str, BundleNodeFact] = {}
    for node_id in sorted(nodes):
        if not graph.has_node(node_id):
            continue
        attrs = graph.nodes[node_id]
        in_relations = sorted(
            {
                str(data.get("relation") or data.get("label") or "")
                for _, _, data in graph.in_edges(node_id, data=True)
                if str(data.get("relation") or data.get("label") or "")
            }
        )
        out_relations = sorted(
            {
                str(data.get("relation") or data.get("label") or "")
                for _, _, data in graph.out_edges(node_id, data=True)
                if str(data.get("relation") or data.get("label") or "")
            }
        )
        out[node_id] = BundleNodeFact(
            node_id=node_id,
            node_kind=str(attrs.get("node_kind") or attrs.get("kind") or attrs.get("entity_kind") or ""),
            universe=_node_universe(attrs),
            defined=bool(attrs.get("defined", False)),
            incoming_relations=in_relations,
            outgoing_relations=out_relations,
        )
    return out


def _collect_edge_facts(graph: nx.DiGraph, nodes: set[str]) -> list[BundleEdgeFact]:
    out: list[BundleEdgeFact] = []
    for u, v, data in graph.edges(data=True):
        if u not in nodes and v not in nodes:
            continue
        source_attrs = graph.nodes[u] if graph.has_node(u) else {}
        target_attrs = graph.nodes[v] if graph.has_node(v) else {}
        out.append(
                BundleEdgeFact(
                    edge_id=str(data.get("edge_id") or f"{u}->{v}"),
                    source=str(u),
                    target=str(v),
                    relation=str(data.get("relation") or data.get("label") or ""),
                    inferred=bool(data.get("inferred", False)),
                    confidence=_edge_confidence(data.get("confidence", 1.0)),
                    source_universe=str(data.get("source_system") or _node_universe(source_attrs)),
                    target_universe=str(data.get("target_system") or _node_universe(target_attrs)),
                    payload_missing_fields=[str(x) for x in data.get("payload_missing_fields", [])],
                    payload_extra_fields=[str(x) for x in data.get("payload_extra_fields", [])],
                )
            )
    return out


def _edge_confidence(raw: object) -> float:
    try:
        return float(raw)
    except (TypeError, ValueError):
        label = str(raw or "").strip().lower()
        return {
            "extracted": 1.0,
            "synthetic": 0.9,
            "inferred": 0.7,
        }.get(label, 1.0)


def _compute_evidence(bundle: ContextBundle) -> BundleEvidence:
    """Score evidence quality so the runner can skip thin bundles.

    Score is in ``[0, 1]``. Mix:

    - 0.40 * min(snippets_full / 3, 1.0)
    - 0.15 * has_seams
    - 0.15 * (has_data_reads or has_data_writes)
    - 0.15 * has_rls_coverage
    - 0.15 * has_migration_state
    """
    counts = {"full": 0, "embedded": 0, "label_only": 0, "missing": 0}
    for snip in bundle.code_snippets:
        counts[snip.evidence_quality] = counts.get(snip.evidence_quality, 0) + 1

    has_seams = bool(bundle.cross_language_seams)
    has_reads = bool(bundle.data_reads)
    has_writes = bool(bundle.data_writes)
    has_rls = bool(bundle.rls_coverage)
    has_migration = bool(bundle.migration_state)

    score = 0.40 * min(counts["full"] / 3.0, 1.0)
    score += 0.15 if has_seams else 0.0
    score += 0.15 if (has_reads or has_writes) else 0.0
    score += 0.15 if has_rls else 0.0
    score += 0.15 if has_migration else 0.0

    missing: list[str] = []
    if counts["full"] == 0:
        missing.append("no_full_snippets")
    if not has_seams:
        missing.append("no_seams")
    if not (has_reads or has_writes):
        missing.append("no_data_io")
    if not has_rls:
        missing.append("no_rls_coverage")
    if not has_migration:
        missing.append("no_migration_state")

    return BundleEvidence(
        snippet_count=len(bundle.code_snippets),
        snippets_full=counts["full"],
        snippets_embedded=counts["embedded"],
        snippets_label_only=counts["label_only"],
        snippets_missing=counts["missing"],
        has_seams=has_seams,
        has_data_reads=has_reads,
        has_data_writes=has_writes,
        has_rls_coverage=has_rls,
        has_migration_state=has_migration,
        evidence_score=round(min(score, 1.0), 4),
        missing_pieces=missing,
    )


# ---------------------------------------------------------------------------
# Truncation
# ---------------------------------------------------------------------------


def _apply_truncation(
    bundle: ContextBundle,
    estimator,
    budget: int,
) -> None:
    """Greedy truncation in the documented order. Writes events to
    ``bundle.truncation_events`` and updates ``bundle.pack_manifest``.
    """

    def total_tokens() -> int:
        return sum(estimator(s.text) for s in bundle.code_snippets)

    events: list[str] = []
    order: list[str] = []

    # Step 0: drop label_only snippets first — they carry no real
    # information beyond what the candidate already has, and they pollute
    # reasoner prompts with strings like just a function name.
    if total_tokens() > budget:
        kept: list[CodeSnippet] = []
        for snip in bundle.code_snippets:
            if snip.evidence_quality == "label_only":
                events.append(f"dropped_label_only_snippet:{snip.node_id}")
                continue
            kept.append(snip)
        if len(kept) < len(bundle.code_snippets):
            order.append("label_only_snippets")
            bundle.code_snippets = kept

    # Step 1: drop least-central call_chain nodes if needed (pure metadata).
    if total_tokens() > budget and bundle.call_chain_out:
        dropped = bundle.call_chain_out.pop()
        events.append(f"dropped_call_chain_out:{dropped.get('node_id')}")
        order.append("call_chain_out_farthest")

    # Step 2: dedup snippets by source_file + first_line.
    if total_tokens() > budget:
        seen_keys: set[tuple[str, int]] = set()
        deduped: list[CodeSnippet] = []
        for snip in bundle.code_snippets:
            key = (snip.source_file or "", snip.start_line)
            if key in seen_keys:
                events.append(f"dropped_duplicate_snippet:{snip.node_id}")
                continue
            seen_keys.add(key)
            deduped.append(snip)
        if len(deduped) < len(bundle.code_snippets):
            order.append("duplicate_snippets")
            bundle.code_snippets = deduped

    # Step 3: head/tail trim the largest snippet repeatedly.
    while total_tokens() > budget and bundle.code_snippets:
        bundle.code_snippets.sort(key=lambda s: -estimator(s.text))
        largest = bundle.code_snippets[0]
        lines = largest.text.splitlines()
        if len(lines) <= 40:
            # Cannot trim further; drop entirely.
            bundle.code_snippets.pop(0)
            events.append(f"dropped_snippet:{largest.node_id}")
            order.append("drop_snippet")
            continue
        trimmed = "\n".join(lines[:20] + ["# ... truncated ..."] + lines[-20:])
        largest.text = trimmed
        events.append(f"trimmed_head_tail:{largest.node_id}")
        order.append("head_tail_trim")

    bundle.truncation_events = events
    bundle.token_budget = total_tokens()
    bundle.pack_manifest.truncated = [e for e in events if e.startswith("trimmed_")]
    bundle.pack_manifest.dropped = [e for e in events if e.startswith("dropped_")]
    bundle.pack_manifest.truncation_order_applied = list(dict.fromkeys(order))


