def _edge_confidence(raw: object) -> float:
    try:
        return float(raw)
    except (TypeError, ValueError):
        label = str(raw or "").strip().lower()
        return {
            "extracted": 1.0,
            "synthetic": 0.9,
            "inferred": 0.7,
        }.get(label, 1.0)

